from typing import List
import heapq

def top_k_elements(nums: List[int], k: int) -> List[int]:
    count = {}
    for num in nums:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    heap = []
    for num, freq in count.items():
        heapq.heappush(heap, (freq, num))
        if len(heap) > k:
            heapq.heappop(heap)

    top_k = [heapq.heappop(heap)[1] for _ in range(len(heap))]
    top_k.reverse()

    return top_k
