from typing import List, Tuple
import heapq

def cheapest_route(edges: List[Tuple[str, str, int]], start: str, goal: str) -> Tuple[int, List[str]] | None:
    graph = {}
    for u, v, w in edges:
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []
        graph[u].append((v, w))
        graph[v].append((u, w))

    if start not in graph or goal not in graph:
        return None

    pq = [(0, start, [start])]
    visited = set()

    while pq:
        (cost, node, path) = heapq.heappop(pq)
        if node == goal:
            return (cost, path)
        if node in visited:
            continue
        visited.add(node)
        for neighbor, weight in graph[node]:
            if neighbor not in visited:
                heapq.heappush(pq, (cost + weight, neighbor, path + [neighbor]))

    return None
