def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    if source == target:
        return 1

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    if target not in graph:
        return 0

    queue = deque([(source, 1)])
    visited = {source}
    path_count = 0

    while queue:
        current, count = queue.popleft()
        if current == target:
            path_count += count
        for neighbor in graph[current]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, count * (len(graph[neighbor]) - 1)))

    return path_count
