import operator

def evaluate_expression(expr: str) -> int:
    def parse_number(tokens):
        return int(tokens.pop(0))

    def parse_unary_minus(tokens):
        if tokens and tokens[-1] == '-':
            tokens.pop()
            return -parse_number(tokens)
        return parse_number(tokens)

    def parse_power(tokens):
        result = parse_unary_minus(tokens)
        while tokens and tokens[-1] == '^':
            tokens.pop()
            result = operator.pow(result, parse_unary_minus(tokens))
        return result

    def parse_term(tokens):
        result = parse_power(tokens)
        while tokens and tokens[-1] in ('*', '/'):
            op = tokens.pop()
            if op == '*':
                result *= parse_power(tokens)
            else:
                divisor = parse_power(tokens)
                if divisor == 0:
                    raise ZeroDivisionError("division by zero")
                result //= divisor
        return result

    def parse_expression(tokens):
        result = parse_term(tokens)
        while tokens and tokens[-1] in ('+', '-'):
            op = tokens.pop()
            if op == '+':
                result += parse_term(tokens)
            else:
                result -= parse_term(tokens)
        return result

    tokens = expr.replace(' ', '').replace('^', '**').split(')')
    for i in range(len(tokens)):
        if '(' in tokens[i]:
            tokens[i] = tokens[i].split('(')
            tokens[i+1:i+1] = tokens[i][1:]
            tokens[i] = tokens[i][0]
    tokens = [token for sublist in tokens for token in sublist.split('(')]
    tokens.reverse()
    return parse_expression(tokens)
