import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    tokens = []
    pattern = re.compile(r'\s+|==|!=|<=|>=|[+\-*/<>=(),]|\d+\.\d+|\d+|[a-zA-Z_]\w*')
    for match in pattern.finditer(source):
        token_text = match.group()
        if token_text.isspace():
            continue
        if token_text == '.':
            raise ValueError("Invalid token: '.'")
        if token_text.isdigit():
            kind = "NUMBER"
        elif token_text.isalpha() or token_text[0] == '_':
            kind = "NAME"
        else:
            kind = "OP"
        tokens.append((kind, token_text))
    return tokens
