def parse_csv(text: str) -> list[list[str]]:
    result = []
    lines = text.split('\n')
    i = 0
    while i < len(lines):
        if lines[i].strip() == '':
            result.append([''])
            i += 1
        else:
            fields = []
            j = 0
            while j < len(lines[i]):
                if lines[i][j] == '"':
                    k = j + 1
                    while k < len(lines[i]) and (lines[i][k] != '"' or lines[i][k-1] == '"'):
                        k += 1
                    if k == len(lines[i]):
                        raise ValueError("Unquoted double quote at end of line")
                    fields.append(lines[i][j+1:k].replace('""', '"'))
                    j = k + 1
                elif lines[i][j] == ',':
                    fields.append('')
                    j += 1
                else:
                    k = j
                    while k < len(lines[i]) and lines[i][k] != ',':
                        k += 1
                    fields.append(lines[i][j:k])
                    j = k
            result.append(fields)
            i += 1
    return result
