def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    if capacity == 0:
        return ([], [])

    cache = {}
    order = []
    results = []

    for operation in operations:
        if operation[0] == "put":
            key, value = operation[1], operation[2]
            if key in cache:
                order.remove(key)
            if len(cache) >= capacity:
                lru_key = order.pop(0)
                del cache[lru_key]
            cache[key] = value
            order.append(key)
        elif operation[0] == "get":
            key = operation[1]
            if key in cache:
                results.append(cache[key])
                order.remove(key)
                order.append(key)
            else:
                results.append(None)

