import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    tokens = []
    i = 0
    while i < len(source):
        if source[i].isspace():
            i += 1
            continue
        if source[i] == '#':
            while i < len(source) and source[i] != '\n':
                i += 1
            continue
        if source[i].isdigit() or (source[i] == '.' and i + 1 < len(source) and source[i + 1].isdigit()):
            match = re.match(r'\d+(\.\d+)?', source[i:])
            if match:
                tokens.append(('NUMBER', match.group(0)))
                i += len(match.group(0))
                continue
        if source[i].isalpha() or source[i] == '_':
            match = re.match(r'[a-zA-Z_][a-zA-Z0-9_]*', source[i:])
            if match:
                tokens.append(('NAME', match.group(0)))
                i += len(match.group(0))
                continue
        if source[i] in '+-*/<>=(),':
            tokens.append(('OP', source[i]))
            i += 1
            continue
        if source[i:i+2] in ['==', '!=', '<=', '>=']:
            tokens.append(('OP', source[i:i+2]))
            i += 2
            continue
        raise ValueError(f"Invalid character at position {i}: {source[i]}")
    return tokens
