def teller_waits(arrivals: list[int], service_times: list[int], tellers: int) -> list[int]:
    if not arrivals or not service_times or tellers <= 0:
        return []

    teller_queues = [[] for _ in range(tellers)]
    result = [0] * len(arrivals)

    for i, (arrival, service_time) in enumerate(zip(arrivals, service_times)):
        for j in range(tellers):
            if not teller_queues[j]:
                teller_queues[j].append((arrival, service_time))
                result[i] = arrival
                break
            else:
                if teller_queues[j][-1][1] <= arrival:
                    teller_queues[j].append((arrival, service_time))
                    result[i] = arrival - teller_queues[j][-2][1]
                    break

    return result
