def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    ip = 0
    instruction_count = 0
    max_instruction_count = 1000

    while ip < len(program) and instruction_count < max_instruction_count:
        instruction = program[ip]
        instruction_count += 1

        parts = instruction.split()
        opcode = parts[0]

        if opcode == 'PUSH':
            if len(parts) != 2:
                raise ValueError("Invalid PUSH instruction")
            stack.append(int(parts[1]))
        elif opcode == 'POP':
            if not stack:
                raise ValueError("POP from empty stack")
            stack.pop()
        elif opcode == 'DUP':
            if not stack:
                raise ValueError("DUP from empty stack")
            stack.append(stack[-1])
        elif opcode == 'SWAP':
            if len(stack) < 2:
                raise ValueError("SWAP with less than 2 elements on stack")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif opcode == 'ADD':
            if len(stack) < 2:
                raise ValueError("ADD with less than 2 elements on stack")
            stack.append(stack.pop() + stack.pop())
        elif opcode == 'SUB':
            if len(stack) < 2:
                raise ValueError("SUB with less than 2 elements on stack")
            stack.append(-stack.pop() + stack.pop())
        elif opcode == 'MUL':
            if len(stack) < 2:
                raise ValueError("MUL with less than 2 elements on stack")
            stack.append(stack.pop() * stack.pop())
        elif opcode == 'JMP':
            if len(parts) != 2:
                raise ValueError("Invalid JMP instruction")
            ip = int(parts[1]) - 1
        elif opcode == 'JZ':
            if len(parts) != 2:
                raise ValueError("Invalid JZ instruction")
