def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix:
        return []

    n = len(matrix)
    result = [row[:] for row in matrix]

    for ring in range((n + 1) // 2):
        ring_length = 4 * (n - 2 * ring) - 4
        if ring_length == 0:
            continue
        k = k % ring_length
        if k < 0:
            k += ring_length

        top = ring
        bottom = n - ring - 1
        left = ring
        right = n - ring - 1

        for i in range(k):
            temp = result[top][left]
            for j in range(left, right):
                result[top][j] = result[top][j + 1]
            for j in range(top, bottom):
                result[j][right] = result[j + 1][right]
            for j in range(right, left, -1):
                result[bottom][j] = result[bottom][j - 1]
            for j in range(bottom, top, -1):
                result[j][left] = result[j - 1][left]
            result[top + 1][left] = temp

    return result
