def identifier_to_snake(name: str) -> str:
    # Remove hyphens and split by underscores
    parts = re.split(r'[-_]', name)
    result = []
    for part in parts:
        # Find positions to insert underscores
        positions = [m.start() for m in re.finditer(r'([a-z])([A-Z])|([A-Z])([A-Z])(?=[a-z])|([0-9])([A-Z])|([A-Z])([0-9])', part)]
        if positions:
            # Insert underscores and convert to lower case
            for pos in reversed(positions):
                part = part[:pos] + '_' + part[pos:]
            result.append(part.lower())
        else:
            result.append(part.lower())
    return '_'.join(result)
