import re

def identifier_to_snake(name: str) -> str:
    if not re.match(r'^[a-zA-Z0-9-_]*$', name):
        return ""

    words = re.split(r'[-_]+', name)
    snake_case = []

    for word in words:
        if not word:
            continue

        pieces = re.findall(r'[a-z]+|[A-Z][a-z]*|[0-9]+', word)
        for piece in pieces:
            if piece.islower() or piece.isdigit():
                snake_case.append(piece)
            elif piece.isupper():
                for i, char in enumerate(piece):
                    if i == 0 or char.islower():
                        snake_case.append(char.lower())
                    else:
                        snake_case.append('_' + char.lower())

    return '_'.join(snake_case)
