def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    blocked = {(r, c) for r, c in blocked if 0 <= r < n and 0 <= c < n}
    def is_safe(board, row, col):
        for r, c in board:
            if r == row or c == col or abs(r - row) == abs(c - col):
                return False
        return True
    def backtrack(board, row):
        if row == n:
            return 1
        count = 0
        for col in range(n):
            if (row, col) not in blocked and is_safe(board, row, col):
                board.append((row, col))
                count += backtrack(board, row + 1)
                board.pop()
        return count
    return backtrack([], 0)
