            if source in final_balances and target in final_balances and amount > 0 and source != target:
                fee = 2
                if final_balances[source] >= amount + fee:
                    final_balances[source] -= (amount + fee)
                    final_balances[target] += amount
                else:
                    failed.append(i)
            else:
                failed.append(i)
        elif action == 'freeze':
            account, = args
            if account in final_balances:
                final_balances[account] = float('-inf')
