def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]:
    order_counts = {}
    order_details = []
    for event in events:
        action, order_id, quantity = event
        if action == "add":
            if order_id in order_counts:
                order_counts[order_id] += quantity
            else:
                order_counts[order_id] = quantity
                order_details.append((order_id, quantity))
        elif action == "remove":
            if order_id in order_counts:
                if order_counts[order_id] > quantity:
                    order_counts[order_id] -= quantity
                elif order_counts[order_id] == quantity:
                    del order_counts[order_id]
                    order_details.remove((order_id, quantity))
                else:
                    raise ValueError("Attempt to remove more than available quantity")
    return order_counts, order_details
