from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    start, end = None, None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start = (r, c)
            elif grid[r][c] == 'E':
                end = (r, c)

    if not start or not end:
        return -1

    queue = deque([(start, 0, False)])
    visited = set()

    while queue:
        (r, c), steps, broke = queue.popleft()
        if (r, c, broke) in visited:
            continue
        visited.add((r, c, broke))

        if (r, c) == end:
            return steps

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == '.':
                    queue.append(((nr, nc), steps + 1, broke))
                elif grid[nr][nc] == '#' and not broke:
                    queue.append(((nr, nc), steps + 1, True))

    return -1
