def restore_session(data: bytes) -> Dict[str, Union[int, str, List[Union[int, str]]]]:
    try:
        # Use BytesIO to safely handle the bytes data
        byte_stream = BytesIO(data)
        # Load the data using pickle
        session_data = pickle.load(byte_stream)
        # Validate the data types
        if not isinstance(session_data, dict):
            raise ValueError("Restored data is not a dictionary")
        for key, value in session_data.items():
            if not isinstance(key, str):
                raise ValueError(f"Key '{key}' is not a string")
            if not isinstance(value, (int, str, list)):
                raise ValueError(f"Value '{value}' is not an integer, string, or list")
            if isinstance(value, list):
                for item in value:
                    if not isinstance(item, (int, str)):
                        raise ValueError(f"Item '{item}' in list is not an integer or string")
        return session_data
    except (pickle.PickleError, EOFError, ValueError) as e:
        raise ValueError("Failed to restore session data") from e
