import operator

def evaluate_expression(expression: str) -> float:
    tokens = expression.replace(' ', '').split()
    operators = {'+': operator.add, '-': operator.sub, '*': operator.mul, '/': operator.truediv, '**': operator.pow}
    stack = []
    op_stack = []

    def apply_operator():
        b = stack.pop()
        a = stack.pop()
        op = op_stack.pop()
        result = op(a, b)
        stack.append(result)

    for token in tokens:
        if token.isdigit() or (token.startswith('-') and token[1:].isdigit()):
            stack.append(float(token))
        elif token in operators:
            while op_stack and operators[token].__name__ in '+-*/' and operators[op_stack[-1]].__name__ in '+-*/':
                apply_operator()
            op_stack.append(token)
        elif token == '(':
            op_stack.append(token)
        elif token == ')':
            while op_stack[-1] != '(':
                apply_operator()
            op_stack.pop()
        else:
            raise ValueError(f"Unknown token: {token}")

    while op_stack:
        apply_operator()

    if len(stack) != 1:
        raise ValueError("Invalid expression")

    return stack[0]
