            while stack and stack[-1] != '(':
                b = stack.pop()
                a = stack.pop()
                stack.append(ops[token](a, b))
            stack.append(token)
        elif token == '(':
            stack.append(token)
        elif token == ')':
            while stack and stack[-1] != '(':
                b = stack.pop()
                a = stack.pop()
                stack.append(ops[stack.pop()](a, b))
            stack.pop()
        else:
            raise ValueError("Unknown token")

