import ast

def matches_filter(expression: str, record: dict) -> bool:
    try:
        # Create a custom NodeTransformer to replace variable names with their values
        class VariableReplacer(ast.NodeTransformer):
            def __init__(self, record):
                self.record = record

            def visit_Name(self, node):
                if node.id in self.record:
                    return ast.copy_location(
                        ast.Num(self.record[node.id]), node
                    )
                else:
                    raise ValueError(f"Unknown variable: {node.id}")

        # Parse the expression into an AST
        parsed_expr = ast.parse(expression, mode='eval').body

        # Replace variable names with their values
        replaced_expr = VariableReplacer(record).visit(parsed_expr)

        # Evaluate the AST
        return eval(compile(replaced_expr, filename="<ast>", mode="eval"))

    except (SyntaxError, ValueError, NameError, TypeError) as e:
        raise ValueError(f"Invalid expression: {e}")
