import ast
import operator as op

ops = {
    ast.Add: op.add, ast.Sub: op.sub, ast.Mult: op.mul,
    ast.Div: op.truediv, ast.Pow: op.pow, ast.BitXor: op.xor,
    ast.USub: op.neg, ast.Lt: op.lt, ast.LtE: op.le, ast.Gt: op.gt,
    ast.GtE: op.ge, ast.Eq: op.eq, ast.NotEq: op.ne, ast.And: op.and_,
    ast.Or: op.or_, ast.Not: op.not_
}

def eval_expr(expr, record):
    return eval_(ast.parse(expr, mode='eval').body, record)

def eval_(node, record):
    if isinstance(node, ast.Num):  # <number>
        return node.n
    elif isinstance(node, ast.BinOp):  # <left> <operator> <right>
        return ops[type(node.op)](eval_(node.left, record), eval_(node.right, record))
    elif isinstance(node, ast.UnaryOp):  # <operator> <operand> e.g., -1
        return ops[type(node.op)](eval_(node.operand, record))
    elif isinstance(node, ast.Name):  # <name>
        return record[node.id]
    else:
        raise TypeError(node)

def matches_filter(expression: str, record: dict) -> bool:
    try:
        return eval_expr(expression, record)
    except (SyntaxError, NameError, TypeError) as e:
        raise ValueError("Invalid expression") from e
