import math
from typing import Callable

def evaluate_formula(formula: str, x: float) -> float:
    def safe_eval(expression: str) -> float:
        def safe_sqrt(value: float) -> float:
            if value < 0:
                raise ValueError("sqrt of negative number")
            return math.sqrt(value)

        def safe_abs(value: float) -> float:
            return abs(value)

        def safe_sin(value: float) -> float:
            return math.sin(value)

        def safe_cos(value: float) -> float:
            return math.cos(value)

        functions: dict[str, Callable[[float], float]] = {
            'sqrt': safe_sqrt,
            'abs': safe_abs,
            'sin': safe_sin,
            'cos': safe_cos
        }

        for name, func in functions.items():
            expression = expression.replace(name, f'({func.__name__}(x))')

        try:
            return eval(expression, {'x': x}, functions)
        except ZeroDivisionError:
            raise
        except Exception as e:
            raise ValueError(f"Invalid formula: {e}")

    return safe_eval(formula)

