    if n == 0:
        return "0"
    digits = []
    while n != 0:
        n, remainder = divmod(n, 3)
        if remainder == 2:
            digits.append('-')
            n += 1
        else:
            digits.append(str(remainder))
    return ''.join(digits[::-1])
