import heapq

def cheapest_route(edges: list[tuple[str, str, int]], start: str, goal: str) -> tuple[int, list[str]] | None:
    graph = {}
    for u, v, w in edges:
        if u not in graph:
            graph[u] = {}
        if v not in graph:
            graph[v] = {}
        graph[u][v] = min(graph[u].get(v, float('inf')), w)
        graph[v][u] = min(graph[v].get(u, float('inf')), w)

    if start not in graph or goal not in graph:
