def find_bridges(n: int, edges: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
    from collections import defaultdict, deque

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    bridges = []
    visited = [False] * n
    disc = [-1] * n
    low = [-1] * n
    parent = [-1] * n

    def dfs(u):
        nonlocal time
        visited[u] = True
        disc[u] = low[u] = time
        time += 1

        for v in graph[u]:
            if not visited[v]:
                parent[v] = u
                dfs(v)
