    from collections import defaultdict, deque

    def dfs(u, parent):
        nonlocal time
        disc[u] = low[u] = time
        time += 1
        stack.append(u)
        children = 0

        for v in graph[u]:
            if disc[v] == -1:
                children += 1
                dfs(v, u)
