def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    # Calculate the width of each column
    column_widths = [max(len(cell) for cell in column) for column in zip(*rows)]

    # Format each row
    formatted_rows = []
    for row in rows:
        formatted_row = []
        for cell, align, width in zip(row, aligns, column_widths):
            if align == 'l':
                formatted_cell = cell.ljust(width)
            elif align == 'r':
                formatted_cell = cell.rjust(width)
            elif align == 'c':
                formatted_cell = cell.center(width)
            formatted_row.append(formatted_cell)
        formatted_rows.append(" | ".join(formatted_row))

    return "\n".join(formatted_rows)
