from math import gcd
from functools import reduce

def lcm(a: int, b: int) -> int:
    return a * b // gcd(a, b)

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    def extended_gcd(a: int, b: int) -> tuple[int, int, int]:
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    def combine_congruences(c1: tuple[int, int], c2: tuple[int, int]) -> tuple[int, int]:
        r1, m1 = c1
        r2, m2 = c2
        gcd, x, _ = extended_gcd(m1, m2)
        if (r1 - r2) % gcd != 0:
            return None
        m = m1 * m2 // gcd
        r = (r1 * (m2 // gcd) * x + r2 * (m1 // gcd)) % m
        return (r, m)

    result = reduce(combine_congruences, congruences)
    if result is None:
        return None
    x, L = result
    return (x, L)
