def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix:
        return []

    n = len(matrix)
    result = [row[:] for row in matrix]

    for ring in range((n + 1) // 2):
        length = 2 * (n - 2 * ring) - 4
        if length <= 0:
            continue
        k = k % length
        if k < 0:
            k += length

        top = ring
        bottom = n - ring - 1
        left = ring
        right = n - ring - 1

        elements = []
        for i in range(left, right + 1):
            elements.append(matrix[top][i])
        for i in range(top + 1, bottom + 1):
            elements.append(matrix[i][right])
        for i in range(right, left - 1, -1):
            elements.append(matrix[bottom][i])
        for i in range(bottom - 1, top, -1):
            elements.append(matrix[i][left])

        elements = elements[k:] + elements[:k]

        index = 0
        for i in range(left, right + 1):
            result[top][i] = elements[index]
            index += 1
        for i in range(top + 1, bottom + 1):
            result[i][right] = elements[index]
            index += 1
        for i in range(right, left - 1, -1):
            result[bottom][i] = elements[index]
            index += 1
        for i in range(bottom - 1, top, -1):
