import re

def identifier_to_snake(name: str) -> str:
    # Remove hyphens and split by underscores
    fragments = re.split(r'[-_]', name)
    words = []
    for fragment in fragments:
        # Insert underscores between words and digits, between digits and letters, etc.
        words.extend(re.findall(r'[a-z]+|[A-Z][a-z]*|[0-9]', fragment))
    # Convert to lowercase and join with underscores
    return '_'.join(word.lower() for word in words)

