        for col in range(n):
            if (row, col) not in blocked and is_safe(board, row, col):
                board[row][col] = 1
                total += backtrack(row + 1, count)
                board[row][col] = 0
        return total

    board = [[0] * n for _ in range(n)]
    return backtrack(0, 0)
