def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number or number == '-' or any(c not in '0123456789abcdefghijklmnopqrstuvwxyz'[:from_base] for c in number):
        raise ValueError("Invalid input")

    if number[0] == '-':
        is_negative = True
        number = number[1:]
    else:
        is_negative = False

    decimal_number = int(number, from_base)

    if decimal_number == 0:
        return '0'

    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    result = []

    while decimal_number > 0:
        result.append(digits[decimal_number % to_base])
        decimal_number //= to_base

    if is_negative:
        result.append('-')

    return ''.join(reversed(result))
