                continue
            if (row, c) in blocked or (row, c) == (row, col):
                return False
        for r, c in zip(range(row, -1, -1), range(col, -1, -1)):
            if (r, c) in blocked or (r, c) == (row, col):
                continue
            if (r, c) in blocked or (r, c) == (row, col):
                return False
        for r, c in zip(range(row, n, 1), range(col, -1, -1)):
            if (r, c) in blocked or (r, c) == (row, col):
