def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    ip = 0
    max_instructions = 1000
    instruction_count = 0

    while ip < len(program) and instruction_count < max_instructions:
        instruction = program[ip]
        parts = instruction.split()
        opcode = parts[0]

        if opcode == 'PUSH':
            stack.append(int(parts[1]))
        elif opcode == 'POP':
            if stack:
                stack.pop()
            else:
                return None
        elif opcode == 'DUP':
            if stack:
                stack.append(stack[-1])
            else:
                return None
        elif opcode == 'SWAP':
            if len(stack) >= 2:
                stack[-1], stack[-2] = stack[-2], stack[-1]
            else:
                return None
        elif opcode == 'ADD':
            if len(stack) >= 2:
                stack.append(stack.pop() + stack.pop())
            else:
                return None
        elif opcode == 'SUB':
            if len(stack) >= 2:
                b = stack.pop()
                a = stack.pop()
                stack.append(a - b)
            else:
                return None
        elif opcode == 'MUL':
            if len(stack) >= 2:
                stack.append(stack.pop() * stack.pop())
            else:
                return None
        elif opcode == 'JMP':
            if len(parts) == 2:
                ip = int(parts[1])
            else:
                return None
        elif opcode == 'JZ':
            if len(parts) == 2:
                if not stack:
                    return None
                if stack.pop() == 0:
                    ip = int(parts[1])
                else:
                    ip += 1
            else:
                return None

        ip += 1
        instruction_count += 1

    if instruction_count >= max_instructions:
        return None

    return stack[::-1]
