def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    ip = 0
    max_instructions = 1000
    instruction_count = 0

    while ip < len(program) and instruction_count < max_instructions:
        instruction = program[ip]
        parts = instruction.split()
        opcode = parts[0]

        if opcode == 'PUSH':
            stack.append(int(parts[1]))
        elif opcode == 'POP':
            if not stack:
                return None
            stack.pop()
        elif opcode == 'DUP':
            if not stack:
                return None
            stack.append(stack[-1])
        elif opcode == 'SWAP':
            if len(stack) < 2:
                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif opcode == 'ADD':
            if len(stack) < 2:
                return None
            stack.append(stack.pop() + stack.pop())
        elif opcode == 'SUB':
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
        elif opcode == 'MUL':
            if len(stack) < 2:
                return None
            stack.append(stack.pop() * stack.pop())
        elif opcode == 'JMP':
            if len(parts) != 2:
                return None
            ip = int(parts[1])
            continue
        elif opcode == 'JZ':
            if len(parts) != 2:
                return None
            if not stack:
                return None
            if stack.pop() == 0:
                ip = int(parts[1])
                continue
            else:
                ip += 1
        else:
            ip += 1

        ip += 1
        instruction_count += 1

    if instruction_count >= max_instructions:
        return None

    return stack

