from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    start, end = None, None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start = (r, c)
            elif grid[r][c] == 'E':
                end = (r, c)

    if not start or not end:
        return -1

    queue = deque([(start, 0, False)])
    visited = set()
    visited.add((start, False))

    while queue:
        (r, c), moves, broke = queue.popleft()
        if (r, c) == end:
            return moves

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == '.' and (nr, nc, broke) not in visited:
                    queue.append(((nr, nc), moves + 1, broke))
                    visited.add((nr, nc, broke))
                elif grid[nr][nc] == '#' and not broke and (nr, nc, True) not in visited:
                    queue.append(((nr, nc), moves + 1, True))
                    visited.add((nr, nc, True))

    return -1
