def evaluate_expression(expression: str) -> float:
    tokens = re.findall(r'\d+\.\d+|\d+|\+|\-|\*|\/|\**|\(|\)', expression)
    operators = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.truediv,
        '**': operator.pow
    }
    stack = []
    operator_stack = []

    def apply_operator():
        right = stack.pop()
        left = stack.pop()
        stack.append(operators[operator_stack.pop()](left, right))

    def precedence(op):
        return 2 if op == '**' else 1 if op in '+-' else 0

    for token in tokens:
        if token.isdigit() or re.match(r'\d+\.\d+', token):
            stack.append(float(token))
        elif token in operators:
            while (operator_stack and operator_stack[-1] != '(' and
