from collections import Counter

def compute_mode(nums: list[int]) -> list[int]:
    if not nums:
        return []

    count = Counter(nums)
    max_freq = max(count.values())
    mode = [num for num, freq in count.items() if freq == max_freq]

    return sorted(mode)

def moving_average(nums: list[float], window: int) -> list[float]:
    if window <= 0 or window > len(nums):
        return []

    averages = []
    for i in range(len(nums) - window + 1):
        window_sum = sum(nums[i:i + window])
        window_avg = round(window_sum / window, 2)
        averages.append(window_avg)

    return averages

def moving_average(nums: list[float], window: int) -> list[float]:
    if window <= 0 or window > len(nums):
        return []

    result = []
    window_sum = sum(nums[:window])
    result.append(round(window_sum / window, 2))

    for i in range(window, len(nums)):
        window_sum += nums[i] - nums[i - window]
        result.append(round(window_sum / window, 2))

    return result

