def min_max_normalize(nums: list[float]) -> list[float]:
    if not nums:
        return []

    min_val = min(nums)
    max_val = max(nums)

    if min_val == max_val:
        return [0.0] * len(nums)

    normalized_nums = [(num - min_val) / (max_val - min_val) for num in nums]
    return [round(num, 2) for num in normalized_nums]
