def count_interval_overlaps(intervals: list[tuple[int, int]]) -> int:
    intervals.sort(key=lambda x: x[0])
    overlaps = 0
    end = float('-inf')
    for start, current_end in intervals:
        if start < end:
            overlaps += 1
        end = max(end, current_end)
    return overlaps
