from typing import List, Tuple
import heapq

def cheapest_route(edges: List[Tuple[str, str, int]], start: str, goal: str) -> Tuple[int, List[str]] | None:
    graph = {}
    for u, v, w in edges:
        if u not in graph:
            graph[u] = {}
        if v not in graph:
            graph[v] = {}
        graph[u][v] = min(graph[u].get(v, float('inf')), w)
        graph[v][u] = min(graph[v].get(u, float('inf')), w)

    if start not in graph or goal not in graph:
        return None

    pq = [(0, start, [start])]
    while pq:
        cost, node, path = heapq.heappop(pq)
        if node == goal:
            return cost, path
        for neighbor, weight in graph[node].items():
            if neighbor not in path:
                new_path = path + [neighbor]
                heapq.heappush(pq, (cost + weight, neighbor, new_path))

    return None
