def cheapest_route(edges: List[Tuple[str, str, int]], start: str, goal: str) -> Tuple[int, List[str]] | None:
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    if start == goal:
        return (0, [start])

    min_cost = float('inf')
    best_path = None

    pq = deque([(0, start, [start])])
    while pq:
