def find_bridges(n: int, edges: list[tuple[int, int]]) -> list[tuple[int, int]]:
    from collections import defaultdict
    from typing import List, Tuple

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    disc = [-1] * n
    low = [-1] * n
    parent = [-1] * n
    bridges = []

    def dfs(u: int, time: int) -> None:
        nonlocal bridges
        disc[u] = low[u] = time
        time += 1

        for v in graph[u]:
            if disc[v] == -1:
                parent[v] = u
                dfs(v, time)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:
                    bridges.append((min(u, v), max(u, v)))
            elif v != parent[u]:
                low[u] = min(low[u], disc[v])

    time = 0
    for i in range(n):
        if disc[i] == -1:
            dfs(i, time)
            time += 1

    return sorted(bridges)
