def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    if source == target:
        return 1

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    distance = [-1] * n
    distance[source] = 0
    queue = deque([source])
    visited[source] = True

    while queue:
        current = queue.popleft()
        for neighbor in graph[current]:
            if not visited[neighbor]:
                visited[neighbor] = True
                distance[neighbor] = distance[current] + 1
                queue.append(neighbor)

    if distance[target] == -1:
        return 0

    count = 0
    queue = deque([target])
    while queue:
        current = queue.popleft()
        if current == source:
            count += 1
        for neighbor in graph[current]:
            if distance[neighbor] == distance[current] - 1:
                queue.append(neighbor)

    return count
