def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix or not matrix[0]:
        return []

    n = len(matrix)
    result = [row[:] for row in matrix]

    for ring in range((n + 1) // 2):
        ring_length = 2 * (n - 2 * ring) - 4
        if ring_length <= 0:
            break
        k = k % ring_length
        if k == 0:
            continue

        top = ring
        bottom = n - ring - 1
        left = ring
        right = n - ring - 1

        for i in range(k):
            temp = matrix[top][left]
            for j in range(left, right):
                matrix[top][j] = matrix[top][j + 1]
            for j in range(top, bottom):
                matrix[j][right] = matrix[j + 1][right]
            for j in range(right, left, -1):
                matrix[bottom][j] = matrix[bottom][j - 1]
            for j in range(bottom, top, -1):
                matrix[j][left] = matrix[j - 1][left]
            matrix[top + 1][left] = temp

    return result
