def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    if any(size > capacity for size in sizes):
        raise ValueError("An item is larger than the bin capacity.")

    bins = []
    for size in sorted(sizes, reverse=True):
        placed = False
        for bin in bins:
            if sum(bin) + size <= capacity:
                bin.append(size)
                placed = True
                break
        if not placed:
            bins.append([size])

    return bins
