def league_table(results: list[tuple[str, str, int, int]]) -> list[tuple[str, int, int, int]]:
    table = defaultdict(lambda: [0, 0, 0, 0])

    for home, away, home_goals, away_goals in results:
        table[home][0] += 1
        table[away][0] += 1
        if home_goals > away_goals:
            table[home][1] += 3
            table[away][1] += 0
        elif home_goals < away_goals:
            table[home][1] += 0
            table[away][1] += 3
        else:
            table[home][1] += 1
            table[away][1] += 1
        table[home][2] += home_goals
        table[home][3] += away_goals
        table[away][2] += away_goals
        table[away][3] += home_goals

    for team, data in table.items():
        data[2] = data[2] - data[3]

    return sorted(table.items(), key=lambda x: (-x[1][1], -x[1][2], -x[1][3], x[0]))

