def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    ip = 0
    max_iterations = 1000
    iterations = 0

    while ip < len(program) and iterations < max_iterations:
        instruction = program[ip]
        parts = instruction.split()
        opcode = parts[0]

        if opcode == 'PUSH':
            n = int(parts[1])
            stack.append(n)
        elif opcode == 'POP':
            if stack:
                stack.pop()
        elif opcode == 'DUP':
            if stack:
                stack.append(stack[-1])
        elif opcode == 'SWAP':
            if len(stack) >= 2:
                stack[-1], stack[-2] = stack[-2], stack[-1]
        elif opcode == 'ADD':
            if len(stack) >= 2:
                b = stack.pop()
                a = stack.pop()
                stack.append(a + b)
        elif opcode == 'SUB':
            if len(stack) >= 2:
                b = stack.pop()
                a = stack.pop()
                stack.append(a - b)
        elif opcode == 'MUL':
            if len(stack) >= 2:
                b = stack.pop()
                a = stack.pop()
                stack.append(a * b)
        elif opcode == 'JMP':
            t = int(parts[1])
