def matches_filter(expression: str, record: dict) -> bool:
    class SafeEval(ast.NodeTransformer):
        def visit_Name(self, node):
            if node.id not in record:
                raise ValueError(f"Unknown variable: {node.id}")
            return ast.NameConstant(record[node.id])

    try:
        parsed_expr = ast.parse(expression, mode='eval').body
        safe_expr = SafeEval().visit(parsed_expr)
        return eval(compile(safe_expr, filename="<ast>", mode="eval"))
    except (SyntaxError, ValueError) as e:
        raise ValueError(f"Invalid expression: {e}")
