import re

def evaluate_expression(expression: str) -> float:
    if not expression:
        raise ValueError("Empty expression")

    tokens = re.findall(r'\d+\.\d+|\d+|\+|\-|\*|\/|\**|\(|\)', expression)

    if not all(token in "+-*/**()0123456789." for token in tokens):
        raise ValueError("Invalid characters in expression")

    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '**': 3}
    stack_ops = []
    stack_vals = []

    for token in tokens:
        if token.isdigit() or '.' in token:
            stack_vals.append(float(token))
        elif token == '(':
            stack_ops.append(token)
        elif token == ')':
            while stack_ops and stack_ops[-1] != '(':
                stack_vals.append(apply_operator(stack_ops.pop(), stack_vals.pop(), stack_vals.pop()))
            stack_ops.pop()
        else:
            while (stack_ops and stack_ops[-1] != '(' and
                   precedence[token] <= precedence[stack_ops[-1]]):
                stack_vals.append(apply_operator(stack_ops.pop(), stack_vals.pop(), stack_vals.pop()))
            stack_ops.append(token)

    while stack_ops:
        stack_vals.append(apply_operator(stack_ops.pop(), stack_vals.pop(), stack_vals.pop()))

