        url = url.split('@')[1]
    if ':' in url:
        host, port = url.split(':')
        if port != '443':
            return False
    else:
        host = url
    if host.endswith('.'):
        host = host[:-1]
    if host == 'localhost' or host.endswith('.localhost'):
